'use strict';
(function(){
 const kinds={restaurant:'Restoran / kafe',shop:'Do‘kon',stop:'Bekat',other:'Boshqa joy'};
 let requestVersion=0;
 function directions(p,mode='walking'){const destination=p.lat!=null?p.lat+','+p.lon:[p.name,p.address,BarakaPlaces[p.city]?.name].filter(Boolean).join(', ');return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(destination)+'&travelmode='+mode+'&dir_action=navigate'}
 function form(type,id){if(type!=='favorite')return null;const p=state.savedPlaces?.find(p=>p.id===id)||{};const field=(name,label,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(String(value??''))}" ${extra}></label>`;return{title:id?'Joyni tahrirlash':'Sevimli joyni saqlash',html:field('name','Joy nomi',p.name,'required maxlength="100"')+`<label class="field">Turi<select name="kind">${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${p.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Kim saqlayapti?<select name="member">${[...new Set([...state.members,p.member].filter(Boolean))].map(m=>`<option ${m===p.member?'selected':''}>${esc(m)}</option>`).join('')}</select></label><label class="field">Shahar<select name="city">${Object.entries(BarakaPlaces).map(([id,c])=>`<option value="${id}" ${(p.city||'tashkent')===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`+field('address','Manzil',p.address,'maxlength="200"')+field('note','Izoh',p.note,'maxlength="300"')+field('lat','Kenglik (latitude)',p.lat,'type="number" step="any" min="-85" max="85"')+field('lon','Uzunlik (longitude)',p.lon,'type="number" step="any" min="-180" max="180"')+`<button type="button" class="secondary" onclick="BarakaFavorites.locate()">Hozir turgan joyim GPS koordinatasi</button><p class="section-text" id="favorite-gps-status">Koordinata ixtiyoriy. Yaqin bekatlar uchun aniq koordinata kiriting. GPS tugmasi hozir turgan joyingizni oladi.</p>`}}
 function commit(type,id,d){if(type!=='favorite')return false;const p={...d,id:id||uid(),lat:d.lat===''?null:Number(d.lat),lon:d.lon===''?null:Number(d.lon)};if(!Object.hasOwn(BarakaPlaces,p.city))throw Error('Shaharni tanlang.');const list=state.savedPlaces||[];const next=list.some(x=>x.id===id)?list.map(x=>x.id===id?p:x):[...list,p];state.savedPlaces=BarakaData.normalize({...state,savedPlaces:next}).savedPlaces;return true}
 function view(){return `<section class="card"><div class="card-head"><div><h2>Oilangizning sevimli joylari</h2><p>Restoran, do‘kon, bekat yoki istalgan manzil. Hisobga kirgan oiladoshlaringiz bilan umumiy saqlanadi.</p></div><button class="primary" onclick="openForm('favorite')">+ Joy saqlash</button></div><label class="field">Qidirish<input type="search" id="favorite-search" placeholder="Nom, manzil yoki oila a’zosi" oninput="BarakaFavorites.filter(this.value)"></label><div id="favorite-list">${rows('')}</div></section><section class="card" id="favorite-stops" aria-live="polite"><h3>Joy yaqinidagi bekatlar</h3><p>Saqlangan joydan «Yaqin bekatlar» tugmasini bosing. Yo‘l Google Maps orqali ochiladi; GPS ruxsatini xarita ilovasi so‘rashi mumkin.</p></section>`}
 function rows(q){q=q.toLocaleLowerCase();return(state.savedPlaces||[]).filter(p=>(p.name+' '+p.address+' '+p.member).toLocaleLowerCase().includes(q)).map(p=>`<article class="favorite-card"><h3>${esc(p.name)}</h3><p>${esc(kinds[p.kind])} · ${esc(p.member)} · ${esc(BarakaPlaces[p.city]?.name||p.city)}</p><p>${esc(p.address)} ${esc(p.note)}</p><div class="settings-actions">${[['walking','Piyoda'],['driving','Avtomobilda'],['transit','Avtobus / transport']].map(([m,label])=>`<a class="secondary" href="${esc(directions(p,m))}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}<button class="secondary" onclick="BarakaFavorites.nearby('${p.id}')">Yaqin bekatlar</button><button class="text-button" onclick="openForm('favorite','${p.id}')">Tahrirlash</button><button class="text-button" onclick="BarakaFavorites.remove('${p.id}')">O‘chirish</button></div></article>`).join('')||empty('Saqlangan joy yo‘q','Sevimli manzilingizni qo‘shing yoki qidiruvni o‘zgartiring.')}
 function remove(id){state.savedPlaces=(state.savedPlaces||[]).filter(p=>p.id!==id);save()}
 function locate(){const status=$('#favorite-gps-status');if(!navigator.geolocation){status.textContent='GPS mavjud emas. Koordinatani qo‘lda kiriting.';return}status.textContent='GPS aniqlanmoqda…';const formNode=$('#entry-form');navigator.geolocation.getCurrentPosition(pos=>{if(!formNode.isConnected||formType!=='favorite')return;formNode.querySelector('[name="lat"]').value=pos.coords.latitude;formNode.querySelector('[name="lon"]').value=pos.coords.longitude;status.textContent='Hozirgi joyingiz koordinatasi olindi.'},()=>{status.textContent='GPS ruxsati berilmadi yoki joylashuv aniqlanmadi.'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
 async function nearby(id){const p=state.savedPlaces?.find(p=>p.id===id),box=$('#favorite-stops'),version=++requestVersion;if(!p)return;if(p.lat==null){box.textContent='Aniq bekatlarni topish uchun joyni tahrirlab koordinatasini kiriting.';return}box.textContent='Yaqin bekatlar yuklanmoqda…';try{const response=await fetch('/api/transit?'+new URLSearchParams({city:p.city,lat:p.lat,lon:p.lon}));const data=await response.json();if(!response.ok)throw Error(data.error||'Bekatlar yuklanmadi.');if(version!==requestVersion||page!=='favorites'||!box.isConnected)return;box.innerHTML=`<h3>${esc(p.name)} yaqinidagi bekatlar</h3><p>${esc(data.source)} · ${data.live?'Operator GPS':'Statik xarita; jonli GPS ulanmagan'}. Yo‘nalishlar xaritada to‘liq bo‘lmasligi mumkin.</p>`+data.stops.map(stop=>{const routes=data.routes.filter(r=>(r.stopIds||[]).includes(stop.id)||(stop.routeIds||[]).includes(r.id));return `<article class="favorite-card"><b>${esc(stop.name)}</b><p>Avtobuslar: ${routes.length?routes.map(r=>esc(r.ref)).join(', '):'Bu bekatning yo‘nalishlari manbada ko‘rsatilmagan'}</p><a class="text-button" target="_blank" rel="noopener noreferrer" href="${esc(directions({...stop,city:p.city}))}">Bekatga piyoda yo‘l ↗</a> <button class="text-button" onclick="BarakaFavorites.saveStop('${stop.id}')">Bekatni saqlash</button></article>`}).join('');if(!data.stops.length)box.innerHTML+='<p>Yaqin bekat topilmadi.</p>';BarakaFavorites.nearbyData={...data,city:p.city}}catch(e){if(version===requestVersion)box.textContent=e.message}}
 function saveStop(id){const t=BarakaFavorites.nearbyData,s=t?.stops.find(s=>s.id===id);if(!s)return;addStop(s,t.city)}
 function addStop(s,city){if((state.savedPlaces||[]).some(p=>p.kind==='stop'&&p.lat===s.lat&&p.lon===s.lon)){toast('Bu bekat allaqachon saqlangan.');return}commit('favorite',null,{name:s.name,kind:'stop',member:state.members[0],city,address:'',note:'',lat:s.lat,lon:s.lon});save()}
 globalThis.BarakaFavorites={titles:{favorites:['Sevimli joylaringiz bir joyda','Oila bilan saqlang, manzilga yo‘l oling.']},views:{favorites:view},form,commit,locate,nearby,remove,directions,saveStop,addStop,filter:q=>{$('#favorite-list').innerHTML=rows(q)}};
})();
